"""Install the DOS HUD atlas only inside the Normal 1A forced-blank frontpanel loader."""
from bor_multiplier_rows_v1512 import correct as base
from bor_restart_burst_v1494 import offset
from bor_split_atlas_v1467 import Code,imm,far
ART=0x2dc000
TIMER=0x2dc800
BOOT=0x2dd600
PUBLISH=0x2dd800
RESET=0x2dd900
OWNER=0x7ee0c0
def boot():
    q=Code(BOOT);q.put('08c23048da')
    def read(a):q.put(far(0xaf,a))
    def write(a):q.put(far(0x8f,a))
    for a,v in ((0x7e275e,3),(0x7e268e,0),(0x7e2758,0),(0x7ee0a3,1)):
        read(a);q.put(imm(0x29,255));q.put(imm(0xc9,v));q.when(0xd0,'done')
    read(0x7e5004);q.put(imm(0x89,128));q.when(0xf0,'done')
    q.put('e220a980');write(0x2115);q.put('c220');q.put(imm(0xa9,0x7480));write(0x2116)
    q.put(imm(0xa2,0));q.lab('copy');q.put(far(0xbf,ART));write(0x2118);q.put('e8e8');q.put(imm(0xe0,len(TILES)));q.put('d0')
    q.put(bytes(((q.labels['copy']-BOOT-len(q.buf)-1)&255,)))
    q.put('e220a906');write(0x2121)
    for v in (0xff,0x7b,0x9d,0x0c):q.put(bytes((0xa9,v)));write(0x2122)
    q.put('a901');write(OWNER+1)
    q.lab('done');q.put('fa6828');write(OWNER);q.put(far(0x5c,0x1287be))
    return q.done()
def clear():
    q=Code(RESET);q.put('08c23048');q.put(far(0xaf,OWNER));q.put(imm(0xc9,0x101));q.when(0xd0,'done')
    q.put('e220a906');q.put(far(0x8f,0x2121))
    for v in (0xff,0x7f,0,0):q.put(bytes((0xa9,v)));q.put(far(0x8f,0x2122))
    q.lab('done');q.put('6828');q.put(far(0x8f,OWNER+1));q.put(far(0x8f,OWNER));q.put(far(0x5c,0x12817e));return q.done()
def publish():
    q=Code(PUBLISH);q.put(far(0x8f,0x7e0470));q.put(far(0xaf,OWNER));q.put(imm(0xc9,0x101));q.when(0xd0,'old')
    q.put(far(0xaf,0x7e0470));q.put(imm(0xc9,0x8a24));q.when(0x90,'old');q.put(imm(0xc9,0x912c));q.when(0xb0,'old')
    q.put('38');q.put(imm(0xe9,0x8a24));q.put('18');q.put(imm(0x69,TIMER&65535));q.put(far(0x8f,0x7e0470))
    q.put(imm(0xa9,0xd056));q.put(far(0x8f,0x7e0473));q.put(imm(0xa9,18));q.put(far(0x8f,0x7e0475))
    q.put('e220a92d');q.put(far(0x5c,0x108a01))
    q.lab('old');q.put(far(0x5c,0x1089ef));return q.done()
def correct(image,symbols):
    r=bytearray(base(image,symbols));assert len(TILES)==2048 and len(ROWS)==1800
    for a,target,before in ((0x1287ba,BOOT,'8fc0e07e'),(0x12817a,RESET,'8fc0e07e'),(0x1089eb,PUBLISH,'8f70047e')):
        i=offset(a);assert r[i:i+4]==bytes.fromhex(before),(hex(a),r[i:i+4].hex());r[i:i+4]=far(0x5c,target)
    assert r[offset(0x108a01):offset(0x108a01)+4]==far(0x8f,0x7e0472)
    assert r[offset(0x12867b):offset(0x12867b)+4]==far(0x8f,OWNER)
    for a,data in ((ART,TILES),(TIMER,ROWS),(BOOT,boot()),(PUBLISH,publish()),(RESET,clear())):
        i=offset(a);assert not any(r[i:i+len(data)]) and not any(a<=v<a+len(data) for t in symbols for v in t.values() if type(v)is int)
        r[i:i+len(data)]=data
    r[0x7fdc:0x7fe0]=bytes.fromhex('ffff0000');crc=sum(r)&65535;r[0x7fdc:0x7fe0]=(65535-crc).to_bytes(2,'little')+crc.to_bytes(2,'little')
    return bytes(r)

TILES=bytes.fromhex('')
ROWS=bytes.fromhex('')
